const input = $input.first().json;

// Get the HTML returned by the HTTP Request node
const html = String(
  input.data ||
  input.body ||
  input.response ||
  ''
);

if (!html) {
  throw new Error('Website HTML not found');
}

// Find all /products/... links
const matches = [
  ...html.matchAll(/href=["']([^"']*\/products\/[^"'?#]+)["']/gi)
];

const seen = new Set();
const products = [];

for (const match of matches) {
  let url = match[1];

  // Convert relative URL to full URL
  if (url.startsWith('/')) {
    url = 'https://stationery.ecosphere.co.in' + url;
  }

  // Remove duplicates
  if (!seen.has(url)) {
    seen.add(url);

    products.push({
      product_url: url
    });
  }
}

if (!products.length) {
  throw new Error('No product links found');
}

return products.map(product => ({
  json: product
}));

const items = $input.all();

if (!items.length) {
  throw new Error('No products available');
}

// Today's date in India
const today = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Kolkata',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).format(new Date());

// Fixed rotation starting date
const startDate = '2026-01-01';

// Convert both dates to UTC day numbers
const todayDay = Math.floor(
  Date.parse(`${today}T00:00:00Z`) / 86400000
);

const startDay = Math.floor(
  Date.parse(`${startDate}T00:00:00Z`) / 86400000
);

const dayNumber = todayDay - startDay;

// Select exactly one product
const index =
  ((dayNumber % items.length) + items.length) %
  items.length;

const selected = items[index];

return [
  {
    json: {
      ...selected.json,

      product_url: selected.json.product_url,
      product_index: index,
      product_number: index + 1,
      total_products: items.length,
      selected_date: today
    },

    binary: selected.binary
  }
];

const input = $input.first().json;

const html = String(
  input.data ||
  input.body ||
  input.response ||
  ''
);

if (!html) {
  throw new Error('Product page HTML not found');
}

// -----------------------------
// Helper functions
// -----------------------------

function clean(text = '') {
  return String(text)
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

function getMeta(property) {
  const regex1 = new RegExp(
    `<meta[^>]+(?:property|name)=["']${property}["'][^>]+content=["']([^"']+)["'][^>]*>`,
    'i'
  );

  const regex2 = new RegExp(
    `<meta[^>]+content=["']([^"']+)["'][^>]+(?:property|name)=["']${property}["'][^>]*>`,
    'i'
  );

  const match =
    html.match(regex1) ||
    html.match(regex2);

  return match ? clean(match[1]) : '';
}

// -----------------------------
// PRODUCT NAME
// -----------------------------

let productName = getMeta('og:title');

if (!productName) {
  const titleMatch =
    html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);

  productName =
    titleMatch ? clean(titleMatch[1]) : '';
}

// -----------------------------
// DESCRIPTION
// -----------------------------

let description =
  getMeta('og:description') ||
  getMeta('description');

// -----------------------------
// REAL PRODUCT IMAGE
// -----------------------------

let productImage =
  getMeta('og:image');

if (productImage.startsWith('//')) {
  productImage = 'https:' + productImage;
}

// -----------------------------
// PRODUCT URL
// -----------------------------

const previous =
  $("Select Today's Product").first().json;

const productUrl =
  previous.product_url || '';

// -----------------------------
// VALIDATION
// -----------------------------

if (!productName) {
  throw new Error('Product name not found');
}

if (!productImage) {
  throw new Error('Product image not found');
}

if (!productUrl) {
  throw new Error('Product URL not found');
}

// -----------------------------
// OUTPUT
// -----------------------------

return [
  {
    json: {
      product_name: productName,
      description: description,
      product_image: productImage,
      product_url: productUrl
    }
  }
];

const ollama = $input.first().json;

// Get REAL product data
const product =
  $("Extract Product Data").first().json;


// =====================================================
// GET OLLAMA RESPONSE
// =====================================================

let raw =
  ollama.response ??
  ollama.output ??
  ollama.text ??
  ollama.data ??
  ollama.message?.content ??
  ollama.content ??
  '';

if (typeof raw !== 'string') {
  raw = JSON.stringify(raw);
}

raw = raw
  .trim()
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '');


// =====================================================
// PARSE JSON
// =====================================================

let parsed = {};

try {

  parsed = JSON.parse(raw);

} catch (error) {

  throw new Error(
    'Could not parse Ollama JSON: ' +
    error.message +
    '\n\nRaw response:\n' +
    raw
  );
}


// =====================================================
// HASHTAGS
// =====================================================

let hashtags = [];

if (Array.isArray(parsed.hashtags)) {

  hashtags = parsed.hashtags
    .map(v => String(v || '').trim())
    .filter(Boolean)
    .slice(0, 10);

} else if (typeof parsed.hashtags === 'string') {

  hashtags = parsed.hashtags
    .split(/\s+/)
    .map(v => v.trim())
    .filter(Boolean)
    .slice(0, 10);

}

const hashtagsText = hashtags.join(' ');


// =====================================================
// INSTAGRAM DATA
// =====================================================

const instagram =
  parsed.instagram &&
  typeof parsed.instagram === 'object'
    ? parsed.instagram
    : {};

const slide1 = instagram.slide_1 || {};
const slide2 = instagram.slide_2 || {};
const slide3 = instagram.slide_3 || {};
const slide4 = instagram.slide_4 || {};


// =====================================================
// FACEBOOK DATA
// =====================================================

const facebook =
  parsed.facebook &&
  typeof parsed.facebook === 'object'
    ? parsed.facebook
    : {};


// =====================================================
// DESIGN
// =====================================================

const design =
  parsed.design &&
  typeof parsed.design === 'object'
    ? parsed.design
    : {};


// =====================================================
// FINAL CAPTION
// =====================================================

const finalCaption = [
  parsed.caption || '',
  hashtagsText,
  product.product_url || ''
]
  .filter(Boolean)
  .join('\n\n')
  .trim();


// =====================================================
// OUTPUT
// =====================================================

return [
  {
    json: {

      // ===============================================
      // REAL WEBSITE PRODUCT
      // ===============================================

      product_name:
        product.product_name || '',

      product_image:
        product.product_image || '',

      product_url:
        product.product_url || '',

      description:
        product.description || '',


      // ===============================================
      // GENERAL SOCIAL CONTENT
      // ===============================================

      hook:
        parsed.hook || '',

      caption:
        parsed.caption || '',

      cta:
        parsed.cta || 'Explore Now',

      hashtags,

      hashtags_text:
        hashtagsText,

      final_caption:
        finalCaption,


      // ===============================================
      // INSTAGRAM — SLIDE 1
      // ===============================================

      ig1_hook:
        slide1.hook || '',

      ig1_headline:
        slide1.headline || '',

      ig1_subheadline:
        slide1.subheadline || '',

      ig1_design_prompt:
        slide1.design_prompt || '',


      // ===============================================
      // INSTAGRAM — SLIDE 2
      // ===============================================

      ig2_heading:
        slide2.heading || '',

      ig2_feature_1:
        slide2.feature_1 || '',

      ig2_feature_2:
        slide2.feature_2 || '',

      ig2_feature_3:
        slide2.feature_3 || '',

      ig2_design_prompt:
        slide2.design_prompt || '',


      // ===============================================
      // INSTAGRAM — SLIDE 3
      // ===============================================

      ig3_heading:
        slide3.heading || '',

      ig3_benefit_1:
        slide3.benefit_1 || '',

      ig3_benefit_2:
        slide3.benefit_2 || '',

      ig3_benefit_3:
        slide3.benefit_3 || '',

      ig3_design_prompt:
        slide3.design_prompt || '',


      // ===============================================
      // INSTAGRAM — SLIDE 4
      // ===============================================

      ig4_headline:
        slide4.headline || '',

      ig4_supporting_text:
        slide4.supporting_text || '',

      ig4_cta:
        slide4.cta || 'Explore Now',

      ig4_website:
        slide4.website ||
        'stationery.ecosphere.co.in',

      ig4_design_prompt:
        slide4.design_prompt || '',


      // ===============================================
      // FACEBOOK SINGLE POST
      // ===============================================

      fb_hook:
        facebook.hook || '',

      fb_headline:
        facebook.headline || '',

      fb_subheadline:
        facebook.subheadline || '',

