const filename = $json.query?.filename || '';

// Allow Instagram slide images:
// ig-slide-1.jpg
// ig-slide-2.jpg
// ig-slide-3.jpg
// ig-slide-4.jpg
const igPattern = /^ig-slide-[1-4]\.jpg$/;

// Allow Facebook image:
// fb-post-12345.jpg
const fbPattern = /^fb-post-\d+\.jpg$/;

// Also allow fixed Facebook filename if we use it later:
// fb-post.jpg
const fbFixedPattern = /^fb-post\.jpg$/;

const isAllowed =
  igPattern.test(filename) ||
  fbPattern.test(filename) ||
  fbFixedPattern.test(filename);

if (!isAllowed) {
  throw new Error(`Invalid image filename: ${filename}`);
}

const filePath =
  '/home/node/.n8n-files/social-images/' + filename;

return [
  {
    json: {
      filename,
      filePath,
    },
  },
];

